    faq: [{"q":"サーチコンソールの登録は無料ですか？","a":"はい、GoogleサーチコンソールはGoogleアカウントがあれば無料で利用できます。有料プランはありません。サイトの所有権確認ができれば、すべての機能を制限なく使えます。"},{"q":"所有権確認がうまくいかない場合はどうすればいいですか？","a":"まずDNS TXTレコードの場合は設定が反映されるまで数分〜数時間かかることがあります。HTMLタグの場合は、headタグ内に正しく貼り付けられているか、キャッシュが残っていないかを確認してください。それでも解決しない場合は、Google公式ヘルプのトラブルシューティングを参照するか、別の確認方法（Googleアナリティクス連携など）を試してください。"},{"q":"検索パフォーマンスのデータはいつから反映されますか？","a":"所有権確認後、通常は24〜48時間以内にデータが表示され始めます。ただし、新しいサイトやアクセスの少ないサイトでは、データが蓄積されるまでにさらに時間がかかる場合があります。古いデータは表示されないため、登録後のデータのみが対象です。"},{"q":"URL検査で「インデックス未登録」と表示されたらどうすればいいですか？","a":"「インデックス登録をリクエスト」をクリックしてクロールを促してください。その後、数日〜1週間程度で再確認します。もし「noindex タグのため除外」などの理由が表示された場合は、該当ページのmeta robotsタグやHTTPヘッダーを修正する必要があります。修正後に再度リクエストしてください。"},{"q":"サイトマップは必ず送信すべきですか？","a":"必須ではありませんが、新規サイトやURL構造が複雑なサイトでは送信を推奨します。サイトマップを送信すると、GoogleがサイトのURLを効率的に発見しやすくなります。ただし、送信しても必ずインデックスされるわけではなく、コンテンツの質や内部リンクも重要です。"}],
