- 不自然な被リンク（関係ない海外サイト、アダルト、スパムサイト）が増えたら否認ツールで対処
- アンカーテキストの偏りがないか確認：特定のキーワードばかりだと不自然
- 急激な増加はかえって危険：自然なペースで増えているかモニタリング

