    faq: [{"q":"トピッククラスターと従来のキーワード単体対策の違いは？","a":"従来は単一ページでキーワードを狙うことが多かったのに対し、トピッククラスターはテーマ全体を網羅し、内部リンクで専門性を示します。Googleはサイト全体の関連性を評価するため、複数記事でテーマをカバーしたほうが上位表示しやすくなります。"},{"q":"ピラーページとクラスター記事の文字数の目安は？","a":"ピラーページは3,000〜5,000文字程度でテーマの全体像を包括的に解説し、クラスター記事は1,500〜3,000文字で特定のサブトピックを深掘りします。ただし文字数よりも検索意図を満たすことを優先してください。"},{"q":"内部リンクは何本くらい設置すればいいですか？","a":"ピラーから各クラスター記事へ1本、各クラスター記事からピラーへ1本を基本に、関連するクラスター同士は自然な文脈で2〜3本が目安です。不自然な大量リンクは避けてください。"},{"q":"トピッククラスターはどのようなサイトに向いていますか？","a":"コンテンツ量が増えてきたサイトや、特定テーマで専門性を高めたい企業サイト・メディアに向いています。記事数が10本以上あるテーマから始めると効果を実感しやすいです。"},{"q":"トピッククラスターの効果はいつ頃現れますか？","a":"サイトの状態や競合にもよりますが、内部リンクの改善とコンテンツ拡充後、2〜3ヶ月で検索順位やクリック率の変化が見え始めることが多いです。ただし効果を保証するものではありません。"}],
